import {useState} from 'react';import {createRoot} from 'react-dom/client';import ProductionStageTrial from '../../components/production-stage-trial';
const date=new Date(Date.now()+7*3600000).toISOString().slice(0,10),at=`${date}T08:00:00+07:00`;
const orders=[{id:'O',lsxCode:'TEST-PHAO',sku:'TEST',name:'Phao mẫu kiểm thử',line:'B',lsxQty:2000,processes:['PHAO','FINAL']},{id:'D',lsxCode:'TEST-KHAC',sku:'TEST2',line:'B',lsxQty:2000,processes:['PACKING']}];
const employees=[{id:'A',name:'Nhân viên A',line:'B',active:true},{id:'B',name:'Nhân viên B',line:'B',active:true}];
const initial={'["O","PHAO"]':{orderId:'O',stage:'PHAO',people:['A'],completed:0,admittedQuantity:2000,status:'running',at,startedAt:at},'["D","PACKING"]':{orderId:'D',stage:'PACKING',people:['B'],completed:0,status:'running',at,startedAt:at}};
const schedules=[{line:'B',approved:true,days:[{date,working:true,hcStart:'08:00',hcEnd:'17:00',lunchStart:'12:00',lunchEnd:'13:00'}],roster:[{date,hc:['A','B'],ot:[]}]}];
function Fixture(){const [state,setState]=useState<any>(initial),[request,setRequest]=useState<any>(null);return <main><h1>Kiểm thử xuất từng phần — dữ liệu giả, không API</h1><button onClick={()=>setRequest({order:orders[0],action:'complete'})}>Xuất PHAO</button><button onClick={()=>setRequest({order:orders[0],action:'start'})}>Nhập FINAL</button><p id="partial-state">Đã xuất {state['["O","PHAO"]'].completed} / 2000 · {state['["O","PHAO"]'].status} · {state['["O","PHAO"]'].people.join(',')}</p><ProductionStageTrial orders={orders} employees={employees} trialState={state} onState={setState} onBack={()=>setRequest(null)} request={request} schedules={schedules}/></main>};createRoot(document.getElementById('root')!).render(<Fixture/>);
